using DataContracts = Microsoft.ApplicationInsights.DataContracts;
using TraceTelemetry = Microsoft.ApplicationInsights.DataContracts.TraceTelemetry;
using EnvironmentFactory = Microsoft.Dynamics.ApplicationPlatform.Environment.EnvironmentFactory;

/// <summary>
/// Telemetry data contract class containing the information context when writing custom traces to Application Insights.
/// </summary>
public class TFMAppInsightsDocQueueTelemetry extends SysApplicationInsightsTelemetryContractBase
{
    private TraceTelemetry traceTelemetry;

}

Method.Source:
private void new()
{
    traceTelemetry = new TraceTelemetry();
    this.initializeTelemetryContext(traceTelemetry.Context);
}

public final static TFMAppInsightsDocQueueTelemetry newFromDocumentQueue(TFMDocumentQueue _documentQueue)
{
    TFMAppInsightsDocQueueTelemetry telemetry = new TFMAppInsightsDocQueueTelemetry();
    Microsoft.Dynamics.BusinessPlatform.ProductInformation.Provider.ProductInfoProvider provider = Microsoft.Dynamics.BusinessPlatform.ProductInformation.Provider.ProductInfoProvider::get_Provider();
    str platformName = provider.get_PlatformVersion();
    str platformBuildVersion = provider.get_PlatformBuildVersion();
    str productVersion = provider.get_ApplicationVersion();
    str productBuildVersion = provider.get_ApplicationBuildVersion();
    TFMDocumentXML requestXML = _documentQueue.RequestXML();

    telemetry.setMessage(strFmt("Document queue - %1",_documentQueue.DocumentType));
    telemetry.setSeverityLevel( _documentQueue.Status == TFMDocumentQueueStatus::Error ?
                                    Microsoft.ApplicationInsights.DataContracts.SeverityLevel::Error :
                                    Microsoft.ApplicationInsights.DataContracts.SeverityLevel::Information);
    if(_documentQueue.Status == TFMDocumentQueueStatus::Error)
    {
        telemetry.addPropertyRequest(TFMHelper::formatXml(requestXML));
    }
    telemetry.addPropertyAadTenantId();
    telemetry.addPropertyActivityId();
    telemetry.addPropertyEnvironmentId();
    telemetry.addPropertyCompanyName(CompanyInfo::find().name());
    telemetry.addPropertyProductVersion(strFmt('%1 (%2)', productVersion, productBuildVersion));
    telemetry.addPropertyPlatformVersion(strFmt('%1 (%2)', platformName, platformBuildVersion));
    telemetry.addPropertyTFMVersion();
    telemetry.addPropertyFeatureName('TFM');
    telemetry.addPropertyDeviceId(_documentQueue.DeviceId);
    telemetry.addPropertyDocumentTypeId(_documentQueue.DocumentType);
    telemetry.addPropertyContentSubject(_documentQueue.ContentSubject);
    telemetry.addPropertyMessageId(_documentQueue.MessageId);
    telemetry.addPropertyProcessMS(_documentQueue.msProccessingStart);
    telemetry.addPropertyCompleteMS(_documentQueue.msProccessingEnd);
    telemetry.addPropertyDeviceAppVersion(TFMDeviceCapabilities::getValue(_documentQueue.DeviceId, TFMConstants::application(), TFMConstants::version()));
    telemetry.addPropertyDevicePlatformVersion(TFMDeviceCapabilities::getValue(_documentQueue.DeviceId, TFMConstants::platform(), TFMConstants::version()));
    telemetry.addPropertyDocumentSize(strLen(requestXML));


    return telemetry;
}

/// <summary>
/// Builder method adding a property to the existing telemetry data contract.
/// </summary>
/// <param name = "_property">Property object to add.</param>
/// <returns>The current telemetry contract.</returns>
public final TFMAppInsightsDocQueueTelemetry addProperty(SysApplicationInsightsProperty _property)
{
    this.addPropertyBase(_property);
    return this;
}

/// <summary>
/// Gets the current native Application Insights trace telemetry contract.
/// </summary>
/// <returns>An instance of <c>Microsoft.ApplicationInsights.DataContracts.TraceTelemetry</c></returns>
public final TraceTelemetry traceTelemetryContract()
{
    return traceTelemetry;
}
